contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 diff) public payable {
        require(msg.sender != caller);
        // Use donate as setup to change sender context; any account can donate.
        (bool ok,) = address(c).call(abi.encodeWithSignature("donate()"));
        require(ok);
        bool reverted; try this.callAdjustDifficulty(caller, diff) { reverted = false; } catch { reverted = true; }
        assert(caller != msg.sender ? reverted : !reverted);
    }
    function callAdjustDifficulty(address caller, uint256 diff) external {
        (bool ok,) = address(c).call(abi.encodeWithSignature("AdjustDifficulty(uint256)", diff));
        if (!ok) revert();
    }
    receive() external payable {}
}

